"use client";
import {
  useState,
  type HTMLAttributes,
  type ReactNode,
  type CSSProperties,
} from "react";
import * as P from "@radix-ui/react-progress";
import { cx } from "./utils";
export type Tone = "neutral" | "brand" | "success" | "warning" | "danger";
export function Badge({
