.cs-loading-pulse > span { position:absolute; inset:0; border-radius:var(--cs-radius-circle); background:currentColor; opacity:.08; transform:scale(.72); animation:cs-loading-breathe-halo 3s ease-in-out infinite; }
.cs-loading-pulse > i { display:block; width:calc(var(--loading-size) / 3); height:calc(var(--loading-size) / 3); border-radius:var(--cs-radius-circle); background:currentColor; transform:scale(.86); opacity:.72; animation:cs-loading-breathe 3s ease-in-out infinite; }
.cs-loading-logo { display:block; width:var(--loading-size); height:var(--loading-size); flex-shrink:0; overflow:visible; transform-origin:center; animation:cs-loading-logo-breathe 2.4s ease-in-out infinite; }
.cs-loading-logo > g { animation:cs-loading-logo-frame 2.4s ease-in-out infinite; }
.cs-loading-logo > [data-part="top"] { animation-delay:-1.8s; }
