            <p role="alert" className="cs-error">
              {error}
            </p>
          )}
          <div className="cs-actions">
            <AD.Cancel asChild>
              <Button disabled={pending} variant="secondary">
                {cancelLabel}
              </Button>
            </AD.Cancel>
            <AD.Action asChild>
              <Button
                variant="danger"
                loading={pending}
                onClick={async (e) => {
                  e.preventDefault();
                  setPending(true);
                  setError("");
                  try {
                    await onConfirm();
                    setOpen(false);
                  } catch (err) {
                    setError(
                      err instanceof Error ? err.message : "操作失败，请重试。",
                    );
                  } finally {
                    setPending(false);
                  }
                }}
              >
                {confirmLabel}
              </Button>
            </AD.Action>
          </div>
        </AD.Content>
      </AD.Portal>
    </AD.Root>
  );
}
