      <div className="cs-form-dialog-actions"><Button variant="secondary" onClick={() => changeOpen(false)}>取消</Button><Button type="submit" loading={pending}>{submitLabel}</Button></div>
    </form>
  </DialogContent></DialogRoot>;
}

