  --cs-shadow-xs: 0 1px 2px rgb(var(--cs-shadow-color) / .05);
  --cs-shadow-sm: 0 1px 3px rgb(var(--cs-shadow-color) / var(--cs-shadow-opacity)), 0 1px 2px rgb(var(--cs-shadow-color) / .06);
  --cs-shadow-md: 0 4px 6px -1px rgb(var(--cs-shadow-color) / var(--cs-shadow-opacity)), 0 2px 4px -2px rgb(var(--cs-shadow-color) / var(--cs-shadow-opacity));
  --cs-shadow-lg: 0 10px 15px -3px rgb(var(--cs-shadow-color) / var(--cs-shadow-opacity)), 0 4px 6px -4px rgb(var(--cs-shadow-color) / var(--cs-shadow-opacity));
  --cs-shadow-xl: 0 20px 25px -5px rgb(var(--cs-shadow-color) / var(--cs-shadow-opacity)), 0 8px 10px -6px rgb(var(--cs-shadow-color) / var(--cs-shadow-opacity));
